package sluispulumi

import (
	"encoding/base64"
	"errors"
	"fmt"

	"filippo.io/age"
	"github.com/pulumi/pulumi-aws/sdk/v7/go/aws/ssm"
	"github.com/pulumi/pulumi-random/sdk/v4/go/random"
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi"
)

// The backup format v2 encrypts each backup with age to a list of recipients
// (`backup.recipients`). The installation owns one keypair, generated by the
// Pulumi program: the recipient is rendered into the backup function's document,
// the identity is a SecureString parameter that ONLY the restore role reads. The
// backup role holds no key that opens a backup.

const (
	// RestoreIdentityName is the secret, in the backup module's namespace, that
	// holds the age identity the restore function decrypts with
	// (`backup.identity` in its document).
	RestoreIdentityName = "restore-identity"

	sidRestoreIdentity         = "SluisRestoreIdentity"
	sidRestoreIdentityKey      = "SluisRestoreIdentityKey"
	sidDenyRestoreIdentity     = "SluisDenyRestoreIdentity"
	sidDenyRestoreIdentityKey  = "SluisDenyRestoreIdentityKey"
	sidKeyDenyRestoreIdentity  = "SluisKeyDenyRestoreIdentity"
	restoreIdentitySeedBytes   = 32
	restoreIdentityLogicalName = "-restore-identity"
)

// RestoreIdentityParameterName is the address of the restore identity on layout
// v5: `/sluis/<instance>/internal/backup/restore-identity`. It holds the secret
// store's byte-codec document (`{"value":"<base64>"}`) of the age identity
// string `AGE-SECRET-KEY-1...`.
func RestoreIdentityParameterName(instance string) string {
	return ModuleSet{Instance: instance}.InternalPrefix(ModuleBackup) + "/" + RestoreIdentityName
}

// restoreIdentityArn is the ARN of that parameter.
func restoreIdentityArn(region, account string, m ModuleSet) string {
	return arnPrefix + "ssm:" + region + ":" + account + ":parameter" + m.InternalPrefix(ModuleBackup) + "/" + RestoreIdentityName
}

// ParseBackupRecipients holds the estate's extra recipients to what age takes:
// `age1...` X25519 recipients. A repeat is dropped; an invalid one is refused.
func ParseBackupRecipients(extra []string) ([]string, error) {
	var out []string
	seen := map[string]bool{}
	var errs []error
	for i, r := range extra {
		if _, err := age.ParseX25519Recipient(r); err != nil {
			errs = append(errs, fmt.Errorf("ExtraRecipients[%d] %q is not an age recipient (age1...): %w", i, r, err))
			continue
		}
		if !seen[r] {
			seen[r] = true
			out = append(out, r)
		}
	}
	if err := errors.Join(errs...); err != nil {
		return nil, fmt.Errorf("sluispulumi: %w", err)
	}
	return out, nil
}

// restoreIdentity is the installation's restore keypair.
type restoreIdentity struct {
	// Recipient is the public half (`age1...`), not a secret.
	Recipient pulumi.StringOutput
	// ParameterName is where the identity is kept.
	ParameterName pulumi.StringOutput
}

// newRestoreIdentity generates the keypair and stores the identity. The seed is
// a RandomBytes with no keepers, so an apply never rotates it (rotating it would
// orphan every backup made to the old recipient); the identity is secret in state
// and in `pulumi up`'s output, and encrypted at rest with the installation's
// parameter key.
func newRestoreIdentity(ctx *pulumi.Context, name string, p *backupPlan, parent pulumi.ResourceOption) (*restoreIdentity, error) {
	seed, err := random.NewRandomBytes(ctx, name+restoreIdentityLogicalName+"-seed",
		&random.RandomBytesArgs{Length: pulumi.Int(restoreIdentitySeedBytes)}, parent)
	if err != nil {
		return nil, fmt.Errorf("sluis restore identity seed: %w", err)
	}
	pair := pulumi.ToSecret(seed.Base64).(pulumi.StringOutput).ApplyT(func(b64 string) ([]string, error) {
		raw, err := base64.StdEncoding.DecodeString(b64)
		if err != nil {
			return nil, fmt.Errorf("sluispulumi: the restore identity seed: %w", err)
		}
		id, rcpt, err := AgeKeypairFromSeed(raw)
		if err != nil {
			return nil, err
		}
		return []string{id, rcpt}, nil
	}).(pulumi.StringArrayOutput)
	identity := pair.Index(pulumi.Int(0))
	doc := identity.ApplyT(secretDocument).(pulumi.StringOutput)

	pargs := &ssm.ParameterArgs{
		Name:        pulumi.String(RestoreIdentityParameterName(p.Instance)),
		Type:        pulumi.String("SecureString"),
		Value:       doc,
		Overwrite:   pulumi.Bool(true),
		Description: pulumi.String("The age identity the restore function decrypts backups with. Read by the restore role only."),
		Tags:        tagMap(p.Tags),
	}
	// Always the installation's key: plan() refuses a plan without one, and a
	// SecureString left to SSM is encrypted with the AWS-managed key.
	pargs.KeyId = pulumi.String(p.ParameterKeyArn)
	param, err := ssm.NewParameter(ctx, name+restoreIdentityLogicalName, pargs, parent)
	if err != nil {
		return nil, fmt.Errorf("sluis restore identity parameter: %w", err)
	}
	return &restoreIdentity{
		// The recipient is derived from a secret, so Pulumi marks it secret; it is the
		// public half, and the estate reads it as an output.
		Recipient:     pulumi.Unsecret(pair.Index(pulumi.Int(1))).(pulumi.StringOutput),
		ParameterName: param.Name,
	}, nil
}

// restoreIdentityAllow is the restore role's read of the identity: the
// parameter, and the parameter key through SSM for that parameter only.
func restoreIdentityAllow(env ModuleEnv) []statement {
	arn := restoreIdentityArn(env.Region, env.Account, env.Modules)
	st := []statement{{
		"Sid": sidRestoreIdentity, "Effect": "Allow", "Action": []string{ssmGetParameter}, "Resource": arn,
	}}
	for _, k := range parameterKeyStatements(env.parameterKey(), []string{kmsDecrypt}, []string{arn}) {
		k["Sid"] = sidRestoreIdentityKey
		st = append(st, k)
	}
	return st
}

// restoreIdentityDeny is what keeps the identity from every role but the
// restore role. The backup role hosts the backup module, whose namespace the
// identity is in, so its allows would otherwise reach it: the parameter itself
// is denied to it, and so is the decryption of that parameter's value (which
// closes GetParametersByPath, authorised on the path and not the parameter).
func restoreIdentityDeny(env ModuleEnv) []statement {
	arn := restoreIdentityArn(env.Region, env.Account, env.Modules)
	return []statement{
		{"Sid": sidDenyRestoreIdentity, "Effect": "Deny", "Action": "ssm:*", "Resource": arn},
		{
			"Sid": sidDenyRestoreIdentityKey, "Effect": "Deny", "Action": []string{kmsDecrypt}, "Resource": "*",
			"Condition": map[string]any{"StringEquals": map[string]any{condParameterArn: arn}},
		},
	}
}
